export function BlogPostCard({ post, featured = false, priority = false }: Readonly<BlogPostCardProps>) {

  return (
    <Link
      href={`/blog/${post.slug}`}
      className="block group h-full border group transition-colors duration-normal   hover:bg-white/2 p-6 border-border hover:border-primary/50"
    >
      <article className="flex flex-col h-full justify-between">
        <div
          className={`flex items-center gap-2 mb-6 border-b pb-4 border-zinc-900`}
        >
          <div className="flex gap-1.5 ">
            <div className="w-2 h-2 bg-primary"></div>
            <div className="w-2 h-2 bg-zinc-500"></div>
            <div className="w-2 h-2 bg-zinc-700"></div>
          </div>
        </div>

        <div className="flex-1">
          <div className="flex font-mono text-sm mr-auto items-center gap-4 text-foreground-muted mb-3 opacity-40 max-w-4xl">
            {post.publishedDate && (
              <time dateTime={post.publishedDate}>
                {formatDate(post.publishedDate)}
              </time>
            )}
            {post.readingTime > 0 && (
              <>
                <span>•</span>
                <span>{post.readingTime} min read</span>
              </>
            )}
          </div>
          <h3 className="text-3xl group-hover:text-primary font-bold text-foreground transition-colors duration-normal tracking-tight">
            {post.title}
          </h3>
          <p className="text-sm md:text-base text-foreground-secondary leading-relaxed group-hover:text-foreground transition-colors duration-normal mt-4 max-w-3xl font-light">
            {post.excerpt}
          </p>
        </div>

        <div className="  gap-4 pt-6 mt-2 border-t border-zinc-900/60">
          <div className="flex flex-wrap gap-2" aria-label="Tags">
            {post.tags.slice(0, 3).map((tag) => (
              <span
                key={tag}
                className="bg-zinc-900/60 text-zinc-400 group-hover:text-zinc-300 px-3 py-1 border border-zinc-800 group-hover:border-zinc-700/80 text-[10px] font-mono uppercase tracking-widest transition-all duration-300 "
              >
                {tag}
              </span>
            ))}
          </div>
        </div>
      </article>
    </Link>
  );
}

'use client';

import { Share2 } from 'lucide-react';
import { IconXTwitter, IconLinkedin } from 'nucleo-social-media';
import * as motion from 'motion/react-client';
import { toast } from 'react-hot-toast';

interface BlogShareProps {
  title: string;
  slug: string;
}

export function BlogShare({ title, slug }: BlogShareProps) {
  const url = `https://rajeevpuri.com.np/blog/${slug}`;

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: title,
          text: `Check out this blog post: ${title}`,
          url: url,
        });
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          console.error('Error sharing:', err);
        }
      }
    } else {
      navigator.clipboard.writeText(url);
      toast.success('Link copied to clipboard!', {
        style: {
          background: '#18181b',
          color: '#fff',
          border: '1px solid #27272a',
          fontSize: '12px',
          fontFamily: 'var(--font-mono)',
        },
      });
    }
  };

  const socialShares = [
    {
      name: 'X',
      icon: <IconXTwitter className="size-3.5" />,
      href: `https://x.com/intent/tweet?text=${encodeURIComponent(title)}&url=${encodeURIComponent(url)}`,
    },
    {
      name: 'LinkedIn',
      icon: <IconLinkedin className="size-3.5" />,
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`,
    },
  ];

  return (
    <div className="flex items-center gap-2 ml-4 pl-4 ">
      {socialShares.map((social) => (
        <motion.a
          key={social.name}
          href={social.href}
          target="_blank"
          rel="noopener noreferrer"
          className="p-1.5  text-foreground-muted hover:text-primary hover:bg-primary/10 transition-all duration-300 border border-border/50 hover:border-primary/30"
          whileHover={{ y: -1 }}
          whileTap={{ scale: 0.95 }}
          title={`Share on ${social.name}`}
        >
          {social.icon}
        </motion.a>
      ))}
      <motion.button
        onClick={handleShare}
        className="p-1.5 rounded-sm bg-primary/5 text-foreground-muted hover:text-primary hover:bg-primary/10 transition-all duration-300 border border-border/50 hover:border-primary/30"
        whileHover={{ y: -1 }}
        whileTap={{ scale: 0.95 }}
        title="Share"
      >
        <Share2 className="size-3.5" />
      </motion.button>
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { cn } from "../../../lib/portfolio/utils";

interface HeadingItem {
  text: string;
  id: string;
  level: number;
}

export function TableOfContents({ headings }: { headings: HeadingItem[] }) {
  const [activeId, setActiveId] = useState<string>("");
  const observer = useRef<IntersectionObserver | null>(null);

  useEffect(() => {
    const handleObserver = (entries: IntersectionObserverEntry[]) => {
      const visibleEntries = entries.filter((entry) => entry.isIntersecting);

      if (visibleEntries.length > 0) {
        // Sort by how close they are to the top of the viewport
        const sorted = visibleEntries.sort(
          (a, b) => a.boundingClientRect.top - b.boundingClientRect.top
        );
        setActiveId(sorted[0].target.id);
      }
    };

    observer.current = new IntersectionObserver(handleObserver, {
      rootMargin: "-100px 0px -70% 0px", // Offset for top nav bar and viewport center focus
    });

    headings.forEach((heading) => {
      const el = document.getElementById(heading.id);
      if (el) observer.current?.observe(el);
    });

    return () => observer.current?.disconnect();
  }, [headings]);

  if (headings.length === 0) return null;

  return (
    <nav className="space-y-4 sticky">
      <div className="relative border-l border-zinc-900 ml-1 py-1 space-y-3.5">
        {headings.map((heading) => {
          const isActive = activeId === heading.id;
          return (
            <a
              key={heading.id}
              href={`#${heading.id}`}
              className={cn(
                "block font-mono text-[11px] font-medium tracking-wide transition-all duration-normal border-l-2 -ml-px pl-4 hover:text-white leading-relaxed",
                heading.level === 3 ? "pl-8 text-[10px]" : "",
                isActive
                  ? "text-primary border-primary font-bold"
                  : "text-zinc-500 border-transparent"
              )}
            >
              {heading.text}
            </a>
          );
        })}
      </div>
    </nav>
  );
}

